import{_ as s,o as e,c as i,aO as n}from"./chunks/framework.vjUPZZJn.js";const m=JSON.parse('{"title":"C++ 链接报错：Dso missing from command line","description":"","frontmatter":{"date":"2026-10-19T10:00:00.000Z","title":"C++ 链接报错：Dso missing from command line","source":[["1-知识/问题记录/GCC11链接报错libfmt-Dso-missing-from-command-line"]],"tags":["编程语言","问题排查","C++","GCC"],"categories":["问题排查"],"permalink":"/pages/9f887e"},"headers":[],"relativePath":"问题排查/C++ 链接报错：Dso missing from command line.md","filePath":"问题排查/C++ 链接报错：Dso missing from command line.md","lastUpdated":1792375471000}'),l={name:"问题排查/C++ 链接报错：Dso missing from command line.md"};function t(r,a,o,d,h,p){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="c-链接报错-dso-missing-from-command-line" tabindex="-1">C++ 链接报错：Dso missing from command line <a class="header-anchor" href="#c-链接报错-dso-missing-from-command-line" aria-label="Permalink to &quot;C++ 链接报错：Dso missing from command line&quot;">​</a></h1> <p>工具链升级（例如从 GCC 9 换到 GCC 11）之后，代码没有改动，链接期却报出 <code>Dso missing from command line</code>。本文写给碰到这类报错的 C/C++ 开发者：先解释这条报错背后的链接器机制，再给出从正确到临时绕过的几种修法，读完可以独立定位并修复同类问题。</p> <h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2> <p>GCC 11.4 下编译链接报错：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lib/aarch64-linux-gnu/libfmt.so.8: error adding symbols: Dso missing from command line</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同样的代码和链接方式在 GCC 9.4 下编译正常。</p> <h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2> <p>这条报错来自 GNU ld 的既定行为，不是 GCC 11 引入的新策略。两个长期机制叠加在一起：</p> <ul><li><strong>不解析间接依赖的符号</strong>。binutils 2.22（2011 年）起，ld 默认不再从间接依赖的动态库解析符号（<code>--no-copy-dt-needed-entries</code> 成为默认）。代码引用了某个库的符号，而这个库没有显式出现在链接命令里、只作为其他库的间接依赖存在时，ld 会拒绝解析，直接报 <code>Dso missing from command line</code>。</li> <li><strong>发行版的 <code>--as-needed</code> 默认补丁</strong>。上游 GNU ld 的默认值是 <code>--no-as-needed</code>，但 Debian/Ubuntu 长期给自家的 ld 打了 <code>--as-needed</code> 默认补丁：命令行里列出但未被直接引用的库不会写进 DT_NEEDED，进一步压缩了隐式依赖被顺带带上的空间。</li></ul> <p>在此基础上，ld 对命令行做从左到右的单向扫描、不回溯，所以库不仅要在命令行里，位置也必须正确：<code>-l</code> 选项要放在引用它符号的目标文件之后。</p> <p>至于「为什么旧工具链能通过、新的不能」，具体触发点随环境而异——链接顺序、依赖库的打包方式、GCC 驱动传给链接器的参数差异都可能参与其中。旧链接能通过，依赖的是宽松时代工具链的偶然行为，并不是受保证的兼容语义；新工具链只是不再容忍这种写法。</p> <h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2> <h3 id="_1-显式补上缺失的库-推荐" tabindex="-1">1. 显式补上缺失的库（推荐） <a class="header-anchor" href="#_1-显式补上缺失的库-推荐" aria-label="Permalink to &quot;1. 显式补上缺失的库（推荐）&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> other.o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-lfmt</code> 必须放在引用它的目标文件之后，顺序反了同样会报错。</p> <h3 id="_2-用-pkg-config-生成链接参数" tabindex="-1">2. 用 pkg-config 生成链接参数 <a class="header-anchor" href="#_2-用-pkg-config-生成链接参数" aria-label="Permalink to &quot;2. 用 pkg-config 生成链接参数&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> other.o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg-config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --libs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fmt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>适合库自带 <code>.pc</code> 文件的场景，避免手写库列表。</p> <h3 id="_3-cmake" tabindex="-1">3. CMake <a class="header-anchor" href="#_3-cmake" aria-label="Permalink to &quot;3. CMake&quot;">​</a></h3> <div class="language-cmake vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">find_package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fmt REQUIRED)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(your_target </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fmt::fmt)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>导入目标由 CMake 负责展开成正确的链接顺序。</p> <h3 id="_4-间接依赖同样要显式声明" tabindex="-1">4. 间接依赖同样要显式声明 <a class="header-anchor" href="#_4-间接依赖同样要显式声明" aria-label="Permalink to &quot;4. 间接依赖同样要显式声明&quot;">​</a></h3> <p>代码没有直接使用 fmt，但链接的某个库依赖它，也属于同一种情形：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lyourlib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-lfmt</code> 放在 <code>-lyourlib</code> 之后。</p> <h3 id="_5-临时绕过-不推荐" tabindex="-1">5. 临时绕过（不推荐） <a class="header-anchor" href="#_5-临时绕过-不推荐" aria-label="Permalink to &quot;5. 临时绕过（不推荐）&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wl,--no-as-needed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lfmt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-Wl,--copy-dt-needed-entries</code> 可以恢复 binutils 2.22 之前「从间接依赖解析符号」的旧行为，同样只应作临时绕过。这两个开关都掩盖了「依赖没有显式声明」这一根本问题，留给后续升级的隐患大于收益。</p> <h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2> <p><code>Dso missing from command line</code> 的根因是隐式依赖：代码用到的库没有以正确的顺序显式出现在链接命令里。这是 ld 多年来的规范行为，新工具链只是不再放行偶然能跑的链接方式。正确做法是把缺失的库补进链接命令（或交给 pkg-config/CMake 生成），而不是用 <code>--no-as-needed</code>、<code>--copy-dt-needed-entries</code> 之类的开关绕过。</p> <h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2> <ul><li><a href="https://stackoverflow.com/questions/24989432/linking-error-dso-missing-from-command-line" target="_blank" rel="noreferrer">Stack Overflow: Linking error: DSO missing from command line</a></li> <li><a href="https://stackoverflow.com/questions/65269574/understanding-linker-error-dso-missing-from-command-line" target="_blank" rel="noreferrer">Stack Overflow: Understanding Linker Error: DSO missing from command line</a></li> <li><a href="https://stackoverflow.com/questions/79405331/why-does-ubuntus-linker-use-as-needed-by-default" target="_blank" rel="noreferrer">Stack Overflow: Why does Ubuntu&#39;s linker use --as-needed by default?</a></li> <li><a href="https://wiki.gentoo.org/wiki/Project:Quality_Assurance/As-needed" target="_blank" rel="noreferrer">Gentoo Wiki: Project:Quality Assurance/As-needed</a></li> <li><a href="https://man7.org/linux/man-pages/man1/ld.1.html" target="_blank" rel="noreferrer">GNU ld 手册：Options（--as-needed / --copy-dt-needed-entries）</a></li></ul>`,57)])])}const k=s(l,[["render",t]]);export{m as __pageData,k as default};
